// SPDX-License-Identifier: MIT
pragma solidity ^0.8.4;

error DeploymentFailed();
error InvalidImplementation();

contract ProxyFactory {
    event ProxyDeployed(address proxy);

    function implementation() external pure returns (address) {
        return address(0);
    }

    function deploy(address target) external returns (address proxy) {
        if (target == address(0)) revert InvalidImplementation();

        bytes memory code = abi.encodePacked(
            hex"602c80600a3d3939f3363d3d373d3d3d363d73",
            bytes20(target),
            hex"5af43d3d93803e606057fd5bf3"
        );

        assembly {
            proxy := create(0, add(code, 0x20), mload(code))
        }

        if (proxy == address(0)) revert DeploymentFailed();

        emit ProxyDeployed(proxy);
    }
}
