pragma solidity ^0.8.20;

interface IERC721 {
    function ownerOf(uint256 tokenId) external view returns (address);
}

contract DataContract {
    address private _owner;
    address private _wrapper;
    address private _merger;
    bool private _closedMergerUpdate;

    struct TokenData {
        uint32 field0;
        uint32 field1;
        uint16 field2;
        uint8 field3;
        bool field4;
        bool field5;
        bytes field6;
        bytes field7;
        bytes field8;
        bytes[] field9;
    }

    mapping(uint256 => TokenData) private _tokenData;

    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    constructor() {
        _owner = msg.sender;
        emit OwnershipTransferred(address(0), _owner);
    }

    modifier onlyOwner() {
        require(_owner == msg.sender, "Ownable: caller is not the owner");
        _;
    }

    modifier onlyMerger() {
        require(_merger == msg.sender, "Not allowed - only merger");
        _;
    }

    modifier onlyTokenOwner(uint256 tokenId) {
        require(IERC721(_wrapper).ownerOf(tokenId) == msg.sender);
        _;
    }

    function owner() external view returns (address) {
        return _owner;
    }

    function wrapper() external view returns (address) {
        return _wrapper;
    }

    function mergerAddress() external view returns (address) {
        return _merger;
    }

    function closedMergerUpdate() external view returns (bool) {
        return _closedMergerUpdate;
    }

    function renounceOwnership() external onlyOwner {
        emit OwnershipTransferred(_owner, address(0));
        _owner = address(0);
    }

    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "Ownable: new owner is the zero address");
        emit OwnershipTransferred(_owner, newOwner);
        _owner = newOwner;
    }

    function updateMerger(address newMerger) external onlyOwner {
        _merger = newMerger;
    }

    function closeUpdateMerger() external onlyOwner {
        _closedMergerUpdate = true;
    }

    function getData(uint256 tokenId) external view returns (TokenData memory) {
        return _tokenData[tokenId];
    }

    function dataHero(uint256 tokenId) external view returns (
        uint32, uint32, uint16, uint8, bool, bool
    ) {
        TokenData storage data = _tokenData[tokenId];
        return (data.field0, data.field1, data.field2, data.field3, data.field4, data.field5);
    }

    function setData(uint256 tokenId, TokenData calldata data) external onlyMerger {
        _setTokenData(tokenId, data);
    }

    function setDataOwner(uint256 tokenId, bytes calldata data) external onlyTokenOwner(tokenId) {
        _tokenData[tokenId].field6 = data;
    }

    function setDataOwner(uint256 tokenId, bytes calldata data, uint8 index) external onlyTokenOwner(tokenId) {
        if (index == 0) _tokenData[tokenId].field6 = data;
        else if (index == 1) _tokenData[tokenId].field7 = data;
        else if (index == 2) _tokenData[tokenId].field8 = data;
    }

    function setDataOwner(uint256 tokenId, bytes calldata data, uint16 value, uint8 index) external onlyTokenOwner(tokenId) {
        _tokenData[tokenId].field2 = value;
        if (index == 0) _tokenData[tokenId].field6 = data;
        else if (index == 1) _tokenData[tokenId].field7 = data;
        else if (index == 2) _tokenData[tokenId].field8 = data;
    }

    function setDataOwner(uint256 tokenId, bytes[3] calldata data, uint16 value, uint8 value2) external onlyTokenOwner(tokenId) {
        _tokenData[tokenId].field2 = value;
        _tokenData[tokenId].field3 = value2;
        _tokenData[tokenId].field6 = data[0];
        _tokenData[tokenId].field7 = data[1];
        _tokenData[tokenId].field8 = data[2];
    }

    function setDataOwner(uint256 tokenId, TokenData calldata data) external onlyTokenOwner(tokenId) {
        _setTokenData(tokenId, data);
    }

    function _setTokenData(uint256 tokenId, TokenData calldata data) internal {
        TokenData storage stored = _tokenData[tokenId];
        stored.field0 = data.field0;
        stored.field1 = data.field1;
        stored.field2 = data.field2;
        stored.field3 = data.field3;
        stored.field4 = data.field4;
        stored.field5 = data.field5;
        stored.field6 = data.field6;
        stored.field7 = data.field7;
        stored.field8 = data.field8;

        delete stored.field9;
        for (uint256 i = 0; i < data.field9.length; i++) {
            stored.field9.push(data.field9[i]);
        }
    }
}
