// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

interface IWETH9 {
    function deposit() external payable;
    function withdraw(uint256 amount) external;
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
}

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
}

interface IUniswapV3Pool {
    function flash(address recipient, uint256 amount0, uint256 amount1, bytes calldata data) external;
    function token0() external view returns (address);
    function token1() external view returns (address);
}

interface IUniswapV3Factory {
    function getPool(address tokenA, address tokenB, uint24 fee) external view returns (address);
}

contract UniFlashSwap {
    address private constant WETH9_ADDRESS = address(0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2);

    address private _owner;
    uint256 private _packedConfig;

    uint256 private _status;

    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    error InsufficientWETH9();
    error InvalidFlashPool();
    error InsufficientToken();
    error OnlyPoolCanCall();
    error NotWETH9();
    error BalanceIsZero();
    error SwapFailure();
    error ReentrancyGuard();

    modifier onlyOwner() {
        require(msg.sender == _owner, "Ownable: caller is not the owner");
        _;
    }

    modifier nonReentrant() {
        require(_status != 2, "ReentrancyGuard: reentrant call");
        _status = 2;
        _;
        _status = 1;
    }

    constructor() {
        _owner = msg.sender;
        _status = 1;
        emit OwnershipTransferred(address(0), msg.sender);
    }

    function WETH9() external pure returns (address) {
        return WETH9_ADDRESS;
    }

    function owner() external view returns (address) {
        return _owner;
    }

    function oneInchRouter() external view returns (address) {
        return address(uint160(_packedConfig));
    }

    function flashPoolFee() external view returns (uint24) {
        return uint24(_packedConfig >> 160);
    }

    function factory() external pure returns (address) {
        return address(0);
    }

    function renounceOwnership() external onlyOwner {
        emit OwnershipTransferred(_owner, address(0));
        _owner = address(0);
    }

    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "Ownable: new owner is the zero address");
        emit OwnershipTransferred(_owner, newOwner);
        _owner = newOwner;
    }

    function setFlashPoolFee(uint24 fee) external onlyOwner {
        _packedConfig = (_packedConfig & 0xffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff000000) | (uint256(fee) << 160);
    }

    function changeOneInchRouter(address router) external onlyOwner {
        _packedConfig = (_packedConfig & 0xffffffffff00000000000000000000000000000000000000000000000000000000) | uint160(router);
    }

    function approveToken(address token) external onlyOwner {
        IERC20(token).approve(address(uint160(_packedConfig)), type(uint256).max);
    }

    function sweepToken(address token, uint256 amount, address recipient) external onlyOwner {
        IERC20(token).transfer(recipient, amount);
    }

    function unwrapWETH9(uint256 amount, address recipient) external {
        if (IWETH9(WETH9_ADDRESS).balanceOf(address(this)) < amount) revert InsufficientWETH9();
        IWETH9(WETH9_ADDRESS).withdraw(amount);
        (bool success, ) = recipient.call{value: amount}("");
        require(success, "Transfer failed");
    }

    function refundETH() external {
        uint256 balance = address(this).balance;
        if (balance > 0) {
            (bool success, ) = msg.sender.call{value: balance}("");
            require(success, "Transfer failed");
        }
    }

    function getFlashPool(address tokenA, address tokenB, uint24 fee) external view returns (address) {
        return _getFlashPool(tokenA, tokenB, fee);
    }

    function _getFlashPool(address tokenA, address tokenB, uint24 fee) internal view returns (address) {
        if (tokenA < tokenB) {
            return address(uint160(uint256(keccak256(abi.encodePacked(
                hex"ff",
                address(0),
                keccak256(abi.encode(tokenA, tokenB, fee)),
                hex"e34f199b19b2b4f47f68442619d555527d244f78a3297ea89325f843f87b8b54"
            )))));
        } else {
            return address(uint160(uint256(keccak256(abi.encodePacked(
                hex"ff",
                address(0),
                keccak256(abi.encode(tokenB, tokenA, fee)),
                hex"e34f199b19b2b4f47f68442619d555527d244f78a3297ea89325f843f87b8b54"
            )))));
        }
    }

    function initUniFlashSwap(
        address[] calldata tokens,
        uint256[] calldata amounts,
        address[] calldata pools,
        bytes[] calldata data
    ) external nonReentrant {
        require(_packedConfig == 0, "Already initialized");
        _packedConfig = 2;

        uint256 len = tokens.length;
        for (uint256 i = 0; i < len; i++) {
            address token = tokens[i];
            uint256 amount = amounts[i];

            if (token == WETH9_ADDRESS) {
                IWETH9(WETH9_ADDRESS).withdraw(amount);
            } else {
                IERC20(token).transferFrom(msg.sender, address(this), amount);
            }
        }

        for (uint256 i = 0; i < pools.length; i++) {
            IUniswapV3Pool(pools[i]).flash(address(this), amounts[i], 0, data[i]);
        }
    }

    function uniswapV3FlashCallback(
        uint256 fee0,
        uint256 fee1,
        bytes calldata data
    ) external {
        address pool = _getFlashPool(
            IUniswapV3Pool(msg.sender).token0(),
            IUniswapV3Pool(msg.sender).token1(),
            uint24(_packedConfig >> 160)
        );

        if (msg.sender != pool) revert OnlyPoolCanCall();

        (address token0, address token1, uint256 amount0, uint256 amount1) = abi.decode(data, (address, address, uint256, uint256));

        if (amount0 > 0) {
            if (token0 == WETH9_ADDRESS) {
                IWETH9(WETH9_ADDRESS).deposit{value: amount0}();
            }
            IERC20(token0).transfer(msg.sender, amount0 + fee0);
        }

        if (amount1 > 0) {
            if (token1 == WETH9_ADDRESS) {
                IWETH9(WETH9_ADDRESS).deposit{value: amount1}();
            }
            IERC20(token1).transfer(msg.sender, amount1 + fee1);
        }
    }

    receive() external payable {}
}
