pragma solidity ^0.8.20;

interface IResolver {
    function getAddress(bytes32 name) external view returns (address);
    function getUIntValue(bytes32 contractName, bytes32 property) external view returns (uint256);
}

interface IAggregator {
    function latestRound() external view returns (uint256);
    function decimals() external view returns (uint8);
    function getRoundData(uint80 roundId) external view returns (
        uint80 roundId_,
        int256 answer,
        uint256 startedAt,
        uint256 updatedAt,
        uint80 answeredInRound
    );
}

contract ExchangeRates {
    address public owner;
    address public nominatedOwner;
    address public resolverAddress;
    address public oracle;
    address public externalRateAggregator;

    mapping(bytes32 => bool) public frozenRates;
    mapping(bytes32 => address) public aggregators;
    mapping(bytes32 => uint256) public aggregatorRoundData;
    uint256 public aggregatorCount;
    mapping(bytes32 => uint256) public rates;
    mapping(bytes32 => uint256) public lastRateUpdateTimes;
    uint256 public invertedKeysCount;
    mapping(bytes32 => uint256) public rateTimestampRounds;

    struct InversePricing {
        uint256 entryPoint;
        uint256 upperLimit;
        uint256 lowerLimit;
        bool frozenAtUpperLimit;
        bool frozenAtLowerLimit;
    }

    mapping(bytes32 => InversePricing) public inversePricing;
    mapping(uint256 => bytes32) public invertedKeys;

    event OwnerNominated(address newOwner);
    event OwnerChanged(address oldOwner, address newOwner);
    event OracleUpdated(address newOracle);
    event RatesUpdated(bytes32[] currencyKeys, uint256[] newRates);
    event RateDeleted(bytes32 currencyKey);
    event AggregatorAdded(bytes32 currencyKey, address aggregator);
    event AggregatorRemoved(bytes32 currencyKey, address aggregator);
    event InversePriceConfigured(bytes32 currencyKey, uint256 entryPoint, uint256 upperLimit, uint256 lowerLimit);
    event InversePriceFrozen(bytes32 currencyKey, uint256 rate, uint256 timestamp, address initiator);
    event CacheUpdated(bytes32 name, address destination);

    modifier onlyOwner() {
        require(msg.sender == owner, "Only the contract owner may perform this action");
        _;
    }

    modifier onlyOracle() {
        require(msg.sender == oracle, "Only the oracle can perform this action");
        _;
    }

    constructor() {
        owner = msg.sender;
    }

    function nominateNewOwner(address _owner) external onlyOwner {
        nominatedOwner = _owner;
        emit OwnerNominated(_owner);
    }

    function acceptOwnership() external {
        require(msg.sender == nominatedOwner, "You must be nominated before you can accept ownership");
        emit OwnerChanged(owner, nominatedOwner);
        owner = nominatedOwner;
        nominatedOwner = address(0);
    }

    function setOracle(address _oracle) external onlyOwner {
        oracle = _oracle;
        emit OracleUpdated(_oracle);
    }

    function resolver() external view returns (address) {
        return resolverAddress;
    }

    function rebuildCache() external {
        // Cache rebuilding logic
    }

    function isResolverCached() external view returns (bool) {
        return true;
    }

    function rateForCurrency(bytes32 currencyKey) external view returns (uint256) {
        return rates[currencyKey];
    }

    function ratesForCurrencies(bytes32[] calldata currencyKeys) external view returns (uint256[] memory) {
        uint256[] memory _rates = new uint256[](currencyKeys.length);
        for (uint256 i = 0; i < currencyKeys.length; i++) {
            _rates[i] = rates[currencyKeys[i]];
        }
        return _rates;
    }

    function updateRates(bytes32[] calldata currencyKeys, uint256[] calldata newRates, uint256 timeSent) external onlyOracle {
        require(currencyKeys.length == newRates.length, "Currency key array length must match rates array length");
        require(timeSent < block.timestamp + 10 minutes, "Time is too far into the future");

        for (uint256 i = 0; i < currencyKeys.length; i++) {
            require(newRates[i] != 0, "Rate is zero");
            rates[currencyKeys[i]] = newRates[i];
            lastRateUpdateTimes[currencyKeys[i]] = timeSent;
        }

        emit RatesUpdated(currencyKeys, newRates);
    }

    function deleteRate(bytes32 currencyKey) external onlyOracle {
        require(rates[currencyKey] != 0, "No rate to delete");
        delete rates[currencyKey];
        delete lastRateUpdateTimes[currencyKey];
        emit RateDeleted(currencyKey);
    }

    function effectiveValue(bytes32 sourceKey, uint256 sourceAmount, bytes32 destKey) external view returns (uint256) {
        uint256 sourceRate = rates[sourceKey];
        uint256 destRate = rates[destKey];
        require(destRate != 0, "Rate is zero");
        return (sourceAmount * sourceRate) / destRate;
    }

    function effectiveValueAndRates(bytes32 sourceKey, uint256 sourceAmount, bytes32 destKey) external view returns (uint256, uint256, uint256) {
        uint256 sourceRate = rates[sourceKey];
        uint256 destRate = rates[destKey];
        return ((sourceAmount * sourceRate) / destRate, sourceRate, destRate);
    }

    function rateIsInvalid(bytes32 currencyKey) external view returns (bool) {
        return _rateIsInvalid(currencyKey);
    }

    function anyRateIsInvalid(bytes32[] calldata currencyKeys) external view returns (bool) {
        for (uint256 i = 0; i < currencyKeys.length; i++) {
            if (_rateIsInvalid(currencyKeys[i])) {
                return true;
            }
        }
        return false;
    }

    function _rateIsInvalid(bytes32 currencyKey) internal view returns (bool) {
        if (rates[currencyKey] == 0) return true;
        uint256 stalePeriod = _getRateStalePeriod();
        return block.timestamp - lastRateUpdateTimes[currencyKey] > stalePeriod;
    }

    function _getRateStalePeriod() internal view returns (uint256) {
        return 3 hours;
    }

    function rateAndInvalid(bytes32 currencyKey) external view returns (uint256, bool) {
        return (rates[currencyKey], _rateIsInvalid(currencyKey));
    }

    function rateIsFrozen(bytes32 currencyKey) external view returns (bool) {
        return frozenRates[currencyKey];
    }

    function freezeRate(bytes32 currencyKey) external {
        require(inversePricing[currencyKey].entryPoint != 0, "No inverted price exists for key");
        require(!frozenRates[currencyKey], "The rate is already frozen");
        frozenRates[currencyKey] = true;
        emit InversePriceFrozen(currencyKey, rates[currencyKey], block.timestamp, msg.sender);
    }

    function setInversePricing(bytes32 currencyKey, uint256 entryPoint, uint256 upperLimit, uint256 lowerLimit, bool freezeAtUpperLimit, bool freezeAtLowerLimit) external onlyOwner {
        require(lowerLimit > 0, "lowerLimit must be above 0");
        require(upperLimit < entryPoint * 2, "upperLimit must be less than double entryPoint");
        require(!(freezeAtUpperLimit && freezeAtLowerLimit), "Cannot freeze at both limits");

        inversePricing[currencyKey] = InversePricing(entryPoint, upperLimit, lowerLimit, freezeAtUpperLimit, freezeAtLowerLimit);
        invertedKeys[invertedKeysCount] = currencyKey;
        invertedKeysCount++;

        emit InversePriceConfigured(currencyKey, entryPoint, upperLimit, lowerLimit);
    }

    function removeInversePricing(bytes32 currencyKey) external onlyOwner {
        require(inversePricing[currencyKey].entryPoint != 0, "No inverted price exists");
        delete inversePricing[currencyKey];
        delete frozenRates[currencyKey];
    }

    function addAggregator(bytes32 currencyKey, address aggregator) external onlyOwner {
        require(aggregators[currencyKey] == address(0), "Aggregator already exists");
        require(aggregator != address(0), "Aggregator address is zero");
        aggregators[currencyKey] = aggregator;
        aggregatorCount++;
        emit AggregatorAdded(currencyKey, aggregator);
    }

    function removeAggregator(bytes32 currencyKey) external onlyOwner {
        require(aggregators[currencyKey] != address(0), "No aggregator exists for key");
        address oldAggregator = aggregators[currencyKey];
        delete aggregators[currencyKey];
        aggregatorCount--;
        emit AggregatorRemoved(currencyKey, oldAggregator);
    }

    function setExternalRateAggregator(address _aggregator) external onlyOwner {
        externalRateAggregator = _aggregator;
    }

    function currencyKeyDecimals(bytes32 currencyKey) external view returns (uint8) {
        address aggregator = aggregators[currencyKey];
        if (aggregator == address(0)) return 18;
        return IAggregator(aggregator).decimals();
    }

    function getCurrentRoundId(bytes32 currencyKey) external view returns (uint256) {
        address aggregator = aggregators[currencyKey];
        require(aggregator != address(0), "No aggregator exists");
        return IAggregator(aggregator).latestRound();
    }

    function rateAndTimestampAtRound(bytes32 currencyKey, uint256 roundId) external view returns (uint256, uint256) {
        address aggregator = aggregators[currencyKey];
        require(aggregator != address(0), "No aggregator exists");
        (, int256 answer, , uint256 updatedAt, ) = IAggregator(aggregator).getRoundData(uint80(roundId));
        return (uint256(answer), updatedAt);
    }

    function getLastRoundIdBeforeElapsedSecs(bytes32 currencyKey, uint256 startingRoundId, uint256 startingTimestamp, uint256 timediff) external view returns (uint256) {
        address aggregator = aggregators[currencyKey];
        require(aggregator != address(0), "No aggregator exists");
        uint256 targetTime = startingTimestamp + timediff;
        uint256 roundId = startingRoundId;
        while (true) {
            (, , , uint256 updatedAt, ) = IAggregator(aggregator).getRoundData(uint80(roundId));
            if (updatedAt >= targetTime) return roundId;
            roundId++;
        }
    }

    function effectiveValueAtRound(bytes32 sourceKey, uint256 sourceAmount, bytes32 destKey, uint256 roundIdSrc, uint256 roundIdDest) external view returns (uint256) {
        (uint256 srcRate, ) = this.rateAndTimestampAtRound(sourceKey, roundIdSrc);
        (uint256 destRate, ) = this.rateAndTimestampAtRound(destKey, roundIdDest);
        return (sourceAmount * srcRate) / destRate;
    }

    function ratesAndUpdatedTimeForCurrencyLastNRounds(bytes32 currencyKey, uint256 numRounds) external view returns (uint256[] memory, uint256[] memory) {
        uint256[] memory _rates = new uint256[](numRounds);
        uint256[] memory timestamps = new uint256[](numRounds);
        uint256 currentRound = this.getCurrentRoundId(currencyKey);
        for (uint256 i = 0; i < numRounds; i++) {
            (_rates[i], timestamps[i]) = this.rateAndTimestampAtRound(currencyKey, currentRound - i);
        }
        return (_rates, timestamps);
    }

    function rateAndUpdatedTime(bytes32 currencyKey) external view returns (uint256, uint256) {
        return (rates[currencyKey], lastRateUpdateTimes[currencyKey]);
    }

    function ratesAndInvalidForCurrencies(bytes32[] calldata currencyKeys) external view returns (uint256[] memory, bool[] memory) {
        uint256[] memory _rates = new uint256[](currencyKeys.length);
        bool[] memory invalid = new bool[](currencyKeys.length);
        for (uint256 i = 0; i < currencyKeys.length; i++) {
            _rates[i] = rates[currencyKeys[i]];
            invalid[i] = _rateIsInvalid(currencyKeys[i]);
        }
        return (_rates, invalid);
    }

    function canFreezeRate(bytes32 currencyKey) external view returns (bool) {
        InversePricing memory ip = inversePricing[currencyKey];
        if (ip.entryPoint == 0) return false;
        uint256 rate = rates[currencyKey];
        return rate >= ip.upperLimit || rate <= ip.lowerLimit;
    }

    function rateIsFlagged(bytes32 currencyKey) external view returns (bool) {
        address aggregator = aggregators[currencyKey];
        if (aggregator == address(0)) return false;
        (, int256 answer, , , ) = IAggregator(aggregator).getRoundData(uint80(IAggregator(aggregator).latestRound()));
        return answer < 0;
    }

    function currencyByExternal(bytes32 externalKey) external view returns (bytes32) {
        return externalKey;
    }

    function aggregatorKeys(uint256) external view returns (bytes32) {
        return bytes32(0);
    }

    function currenciesUsingAggregator(address) external view returns (bytes32[] memory) {
        bytes32[] memory result = new bytes32[](0);
        return result;
    }

    function aggregatorWarningFlags() external view returns (uint256) {
        return 0;
    }

    function roundFrozen(bytes32 currencyKey) external view returns (uint256) {
        return frozenRates[currencyKey] ? 1 : 0;
    }

    function currentRoundForRate(bytes32 currencyKey) external view returns (uint256) {
        address aggregator = aggregators[currencyKey];
        if (aggregator == address(0)) return 0;
        return IAggregator(aggregator).latestRound();
    }

    function setCurrencyToExternalAggregator(bytes32 currencyKey, bool useExternal) external onlyOwner {
        // Sets whether currency uses external aggregator
    }

    function requireAndGetAddress(bytes32 name, string calldata reason) external view returns (address) {
        address found = IResolver(resolverAddress).getAddress(name);
        require(found != address(0), reason);
        return found;
    }
}
