// SPDX-License-Identifier: MIT
pragma solidity ^0.8.17;

interface IERC20 {
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

interface IERC721Receiver {
    function onERC721Received(address operator, address from, uint256 tokenId, bytes calldata data) external returns (bytes4);
}

contract RainCheck {
    string private _name;
    string private _symbol;
    string private _baseURI;

    mapping(uint256 => address) private _owners;
    mapping(address => uint256) private _balances;
    mapping(uint256 => address) private _tokenApprovals;
    mapping(address => mapping(address => bool)) private _operatorApprovals;

    mapping(address => mapping(uint256 => uint256)) private _ownedTokensIndex;
    mapping(address => uint256[]) private _ownedTokens;
    uint256 private _totalSupply;
    mapping(uint256 => uint256) private _allTokensIndex;
    uint256[] private _allTokens;

    uint256 private _packed; // paused (byte 0) + owner (bytes 1-20)
    address private _collection;
    address private _feeToken;

    // Token data at slot 0x0f
    mapping(uint256 => address) private _tokenTo;
    mapping(uint256 => uint256) private _tokenAmount;
    mapping(uint256 => uint256) private _tokenStakeTime;
    mapping(uint256 => uint256) private _tokenLimitTime;
    mapping(uint256 => uint256) private _tokenFlags; // isEth (byte 0) + exchanged (byte 1)
    mapping(uint256 => uint256) private _tokenFee;
    mapping(uint256 => address) private _tokenErc20;

    event Transfer(address indexed from, address indexed to, uint256 indexed tokenId);
    event Approval(address indexed owner, address indexed approved, uint256 indexed tokenId);
    event ApprovalForAll(address indexed owner, address indexed operator, bool approved);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    error Paused();
    error InvalidAmount();
    error InsufficientFee();
    error NotOwner();
    error NotApproved();
    error TokenNotFound();
    error TransferToZeroAddress();
    error MintToZeroAddress();
    error TokenAlreadyMinted();
    error IndexOutOfBounds();
    error NotERC721Receiver();
    error TimeNotReached();
    error TransferFailed();
    error ZeroAddress();
    error AlreadyExchanged();

    constructor(string memory name_, string memory symbol_, address feeToken_, address collection_) {
        _name = name_;
        _symbol = symbol_;
        _feeToken = feeToken_;
        _collection = collection_;
        _setOwner(msg.sender);
    }

    modifier whenNotPaused() {
        if (paused()) revert Paused();
        _;
    }

    modifier onlyOwner() {
        if (msg.sender != owner()) revert NotOwner();
        _;
    }

    function paused() public view returns (bool) {
        return uint8(_packed) == 1;
    }

    function owner() public view returns (address) {
        return address(uint160(_packed >> 8));
    }

    function _setOwner(address newOwner) private {
        address oldOwner = owner();
        _packed = (_packed & 0xff) | (uint256(uint160(newOwner)) << 8);
        emit OwnershipTransferred(oldOwner, newOwner);
    }

    function renounceOwnership() external onlyOwner {
        _setOwner(address(0));
    }

    function transferOwnership(address newOwner) external onlyOwner {
        if (newOwner == address(0)) revert ZeroAddress();
        _setOwner(newOwner);
    }

    function name() external view returns (string memory) {
        return _name;
    }

    function symbol() external view returns (string memory) {
        return _symbol;
    }

    function baseURI() public view returns (string memory) {
        return _baseURI;
    }

    function collection() external view returns (address) {
        return _collection;
    }

    function feeToken() external view returns (address) {
        return _feeToken;
    }

    function balanceOf(address owner_) public view returns (uint256) {
        if (owner_ == address(0)) revert TokenNotFound();
        return _balances[owner_];
    }

    function ownerOf(uint256 tokenId) public view returns (address) {
        address owner_ = _owners[tokenId];
        if (owner_ == address(0)) revert TokenNotFound();
        return owner_;
    }

    function getApproved(uint256 tokenId) public view returns (address) {
        if (_owners[tokenId] == address(0)) revert TokenNotFound();
        return _tokenApprovals[tokenId];
    }

    function isApprovedForAll(address owner_, address operator) public view returns (bool) {
        return _operatorApprovals[owner_][operator];
    }

    function approve(address to, uint256 tokenId) external {
        address owner_ = ownerOf(tokenId);
        if (msg.sender != owner_ && !isApprovedForAll(owner_, msg.sender)) revert NotApproved();
        if (to == owner_) revert NotApproved();
        _tokenApprovals[tokenId] = to;
        emit Approval(owner_, to, tokenId);
    }

    function setApprovalForAll(address operator, bool approved) external {
        if (operator == msg.sender) revert NotApproved();
        _operatorApprovals[msg.sender][operator] = approved;
        emit ApprovalForAll(msg.sender, operator, approved);
    }

    function _exists(uint256 tokenId) internal view returns (bool) {
        return _owners[tokenId] != address(0);
    }

    function _isApprovedOrOwner(address spender, uint256 tokenId) internal view returns (bool) {
        address owner_ = ownerOf(tokenId);
        return spender == owner_ || getApproved(tokenId) == spender || isApprovedForAll(owner_, spender);
    }

    function _transfer(address from, address to, uint256 tokenId) internal {
        if (to == address(0)) revert TransferToZeroAddress();

        _tokenApprovals[tokenId] = address(0);
        emit Approval(ownerOf(tokenId), address(0), tokenId);

        _balances[from] -= 1;
        _balances[to] += 1;
        _owners[tokenId] = to;

        _removeTokenFromOwnerEnumeration(from, tokenId);
        _addTokenToOwnerEnumeration(to, tokenId);

        emit Transfer(from, to, tokenId);
    }

    function transferFrom(address from, address to, uint256 tokenId) external {
        if (!_isApprovedOrOwner(msg.sender, tokenId)) revert NotApproved();
        _transfer(from, to, tokenId);
    }

    function safeTransferFrom(address from, address to, uint256 tokenId) external {
        safeTransferFrom(from, to, tokenId, "");
    }

    function safeTransferFrom(address from, address to, uint256 tokenId, bytes memory data) public {
        if (!_isApprovedOrOwner(msg.sender, tokenId)) revert NotApproved();
        _safeTransfer(from, to, tokenId, data);
    }

    function _safeTransfer(address from, address to, uint256 tokenId, bytes memory data) internal {
        _transfer(from, to, tokenId);
        _checkOnERC721Received(from, to, tokenId, data);
    }

    function _checkOnERC721Received(address from, address to, uint256 tokenId, bytes memory data) private {
        if (to.code.length > 0) {
            try IERC721Receiver(to).onERC721Received(msg.sender, from, tokenId, data) returns (bytes4 retval) {
                if (retval != IERC721Receiver.onERC721Received.selector) revert NotERC721Receiver();
            } catch {
                revert NotERC721Receiver();
            }
        }
    }

    function _mint(address to, uint256 tokenId) internal {
        if (to == address(0)) revert MintToZeroAddress();
        if (_exists(tokenId)) revert TokenAlreadyMinted();

        _balances[to] += 1;
        _owners[tokenId] = to;

        _addTokenToOwnerEnumeration(to, tokenId);
        _addTokenToAllTokensEnumeration(tokenId);

        _totalSupply += 1;

        emit Transfer(address(0), to, tokenId);
    }

    function _burn(uint256 tokenId) internal {
        address owner_ = ownerOf(tokenId);

        _tokenApprovals[tokenId] = address(0);
        emit Approval(owner_, address(0), tokenId);

        _balances[owner_] -= 1;
        _owners[tokenId] = address(0);

        _removeTokenFromOwnerEnumeration(owner_, tokenId);
        _removeTokenFromAllTokensEnumeration(tokenId);

        _totalSupply -= 1;

        emit Transfer(owner_, address(0), tokenId);
    }

    function _addTokenToOwnerEnumeration(address to, uint256 tokenId) private {
        uint256 length = balanceOf(to);
        _ownedTokens[to].push(tokenId);
        _ownedTokensIndex[to][tokenId] = length;
    }

    function _removeTokenFromOwnerEnumeration(address from, uint256 tokenId) private {
        uint256 lastTokenIndex = balanceOf(from) - 1;
        uint256 tokenIndex = _ownedTokensIndex[from][tokenId];

        if (tokenIndex != lastTokenIndex) {
            uint256 lastTokenId = _ownedTokens[from][lastTokenIndex];
            _ownedTokens[from][tokenIndex] = lastTokenId;
            _ownedTokensIndex[from][lastTokenId] = tokenIndex;
        }

        _ownedTokens[from].pop();
        delete _ownedTokensIndex[from][tokenId];
    }

    function _addTokenToAllTokensEnumeration(uint256 tokenId) private {
        _allTokensIndex[tokenId] = _allTokens.length;
        _allTokens.push(tokenId);
    }

    function _removeTokenFromAllTokensEnumeration(uint256 tokenId) private {
        uint256 lastTokenIndex = _allTokens.length - 1;
        uint256 tokenIndex = _allTokensIndex[tokenId];

        if (tokenIndex != lastTokenIndex) {
            uint256 lastTokenId = _allTokens[lastTokenIndex];
            _allTokens[tokenIndex] = lastTokenId;
            _allTokensIndex[lastTokenId] = tokenIndex;
        }

        _allTokens.pop();
        delete _allTokensIndex[tokenId];
    }

    function totalSupply() public view returns (uint256) {
        return _totalSupply;
    }

    function tokenOfOwnerByIndex(address owner_, uint256 index) external view returns (uint256) {
        if (index >= balanceOf(owner_)) revert IndexOutOfBounds();
        return _ownedTokens[owner_][index];
    }

    function tokenByIndex(uint256 index) external view returns (uint256) {
        if (index >= totalSupply()) revert IndexOutOfBounds();
        return _allTokens[index];
    }

    function tokenURI(uint256 tokenId) external view returns (string memory) {
        if (!_exists(tokenId)) revert TokenNotFound();
        return baseURI();
    }

    function supportsInterface(bytes4 interfaceId) public pure returns (bool) {
        return interfaceId == 0x01ffc9a7 || interfaceId == 0x80ac58cd || interfaceId == 0x5b5e139f;
    }

    function _whitelist(address account) internal view returns (bool) {
        return account.code.length > 0;
    }

    function _delegate() internal view returns (address) {
        return msg.sender;
    }

    function _isEth(uint256 tokenId) internal view returns (bool) {
        return (_tokenFlags[tokenId] & 1) == 1;
    }

    function _isExchanged(uint256 tokenId) internal view returns (bool) {
        return (_tokenFlags[tokenId] & 2) == 2;
    }

    function _setExchanged(uint256 tokenId) internal {
        _tokenFlags[tokenId] |= 2;
    }

    function rainCheckStakeEth(address to, uint256 amount, uint256 limitTime, string calldata) external payable whenNotPaused {
        if (amount == 0) revert InvalidAmount();
        if (msg.value < amount) revert InsufficientFee();

        uint256 tokenId = totalSupply();
        _mint(to, tokenId);

        _tokenTo[tokenId] = msg.sender;
        _tokenAmount[tokenId] = amount;
        _tokenStakeTime[tokenId] = block.timestamp;
        _tokenLimitTime[tokenId] = limitTime;
        _tokenFlags[tokenId] = 1; // isEth = true
        _tokenFee[tokenId] = 0;
        _tokenErc20[tokenId] = address(0);
    }

    function rainCheckStakeErc20(address to, uint256 amount, address erc20, uint256 fee, uint256 limitTime, string calldata) external whenNotPaused {
        if (amount == 0) revert InvalidAmount();

        IERC20(erc20).transferFrom(msg.sender, address(this), amount);

        uint256 tokenId = totalSupply();
        _mint(to, tokenId);

        _tokenTo[tokenId] = msg.sender;
        _tokenAmount[tokenId] = amount;
        _tokenStakeTime[tokenId] = block.timestamp;
        _tokenLimitTime[tokenId] = limitTime;
        _tokenFlags[tokenId] = 0; // isEth = false
        _tokenFee[tokenId] = fee;
        _tokenErc20[tokenId] = erc20;
    }

    function rainCheckWithdraw(uint256 tokenId) external whenNotPaused {
        if (!_isApprovedOrOwner(msg.sender, tokenId)) revert NotOwner();
        if (_isExchanged(tokenId)) revert AlreadyExchanged();
        if (block.timestamp < _tokenLimitTime[tokenId]) revert TimeNotReached();

        address to = _tokenTo[tokenId];
        uint256 amount = _tokenAmount[tokenId];

        _setExchanged(tokenId);

        if (_isEth(tokenId)) {
            (bool success, ) = payable(to).call{value: amount}("");
            if (!success) revert TransferFailed();
        } else {
            IERC20(_tokenErc20[tokenId]).transfer(to, amount);
        }

        _burn(tokenId);
    }

    function rainCheckVoid(uint256 tokenId) external whenNotPaused {
        if (!_isApprovedOrOwner(msg.sender, tokenId)) revert NotOwner();
        if (_isExchanged(tokenId)) revert AlreadyExchanged();

        address to = _tokenTo[tokenId];
        uint256 amount = _tokenAmount[tokenId];

        _setExchanged(tokenId);

        if (_isEth(tokenId)) {
            (bool success, ) = payable(to).call{value: amount}("");
            if (!success) revert TransferFailed();
        } else {
            IERC20(_tokenErc20[tokenId]).transfer(to, amount);
        }

        _burn(tokenId);
    }
}
