contract LimitOrderBook {
    uint256 private constant DIVISOR = 10000;
    uint256 private constant MAX_FEE_PERCENTAGE = 500;

    address private _owner;
    uint256 private _status;
    address private _router;
    address private _pair;
    uint256 private _feePercentage;
    uint256 private _totalFeesCollected;
    mapping(uint256 => Order) private _orders;
    mapping(uint256 => uint256) private _orderQueue;
    mapping(uint256 => uint256) private _orderIndex;
    mapping(bytes32 => uint256) private _orderHashToId;
    uint256 private _orderCounter;
    uint256 private _minOrderSize;
    uint256 private _maxOrderSize;
    uint256 private _maxPriceDeviation;
    uint256 private _ttl;

    struct Order {
        address owner;
        uint8 orderType;
        uint256 amount;
        uint256 price;
        uint256 filledAmount;
        uint256 priceAtCreation;
        uint256 remainingAmount;
        uint256 timestamp;
        uint8 status;
    }

    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
    event OrderCreated(uint256 indexed orderId, address indexed owner, uint256 amount, uint256 price, bool isBuy, uint8 orderType);
    event OrderCancelled(uint256 indexed orderId);
    event OrderExpired(uint256 indexed orderId);
    event OrderFulfilled(uint256 indexed orderId, uint256 filledAmount);
    event FeePercentageUpdated(uint256 oldPercentage, uint256 newPercentage);
    event FeesWithdrawn(address indexed to, uint256 amount);

    modifier onlyOwner() {
        if (msg.sender != _owner) revert OwnableUnauthorizedAccount(msg.sender);
        _;
    }

    modifier nonReentrant() {
        if (_status == 2) revert ReentrancyGuardReentrantCall();
        _status = 2;
        _;
        _status = 1;
    }

    constructor(address router_) {
        _owner = msg.sender;
        _router = router_;
        _status = 1;
        _feePercentage = 30;
        _minOrderSize = 10000;
        _maxOrderSize = 10000 * 1e18;
        _maxPriceDeviation = 500;
        _ttl = 500;
        emit OwnershipTransferred(address(0), msg.sender);
    }

    function owner() external view returns (address) {
        return _owner;
    }

    function renounceOwnership() external onlyOwner {
        _transferOwnership(address(0));
    }

    function transferOwnership(address newOwner) external onlyOwner {
        if (newOwner == address(0)) revert OwnableInvalidOwner(address(0));
        _transferOwnership(newOwner);
    }

    function _transferOwnership(address newOwner) internal {
        address oldOwner = _owner;
        _owner = newOwner;
        emit OwnershipTransferred(oldOwner, newOwner);
    }

    function router() external view returns (address) {
        return _router;
    }

    function feePercentage() external view returns (uint256) {
        return _feePercentage;
    }

    function setFeePercentage(uint256 feePercentage_) external onlyOwner {
        if (feePercentage_ > MAX_FEE_PERCENTAGE) revert FeePercentageTooHigh();
        uint256 oldPercentage = _feePercentage;
        _feePercentage = feePercentage_;
        emit FeePercentageUpdated(oldPercentage, feePercentage_);
    }

    function minOrderSize() external view returns (uint256) {
        return _minOrderSize;
    }

    function maxOrderSize() external view returns (uint256) {
        return _maxOrderSize;
    }

    function maxPriceDeviation() external view returns (uint256) {
        return _maxPriceDeviation;
    }

    function updateMaxPriceDeviation(uint256 maxPriceDeviation_) external onlyOwner {
        if (maxPriceDeviation_ < 10000) revert PriceDifferenceTooLarge();
        _maxPriceDeviation = maxPriceDeviation_;
    }

    function totalFeesCollected() external view returns (uint256) {
        return _totalFeesCollected;
    }

    function withdrawFees(address to) external onlyOwner {
        if (_totalFeesCollected == 0) revert NoFeesToWithdraw();
        uint256 amount = _totalFeesCollected;
        _totalFeesCollected = 0;
        (bool success, ) = to.call{value: amount}("");
        if (!success) revert ETHTransferToSellerFailed();
        emit FeesWithdrawn(to, amount);
    }

    function getOrder(uint256 orderId) external view returns (
        address owner_,
        uint256 amount,
        uint256 price,
        uint256 filledAmount,
        uint256 remainingAmount,
        uint256 timestamp,
        uint8 status,
        uint8 orderType
    ) {
        Order storage order = _orders[orderId];
        return (
            order.owner,
            order.amount,
            order.price,
            order.filledAmount,
            order.remainingAmount,
            order.timestamp,
            order.status,
            order.orderType
        );
    }

    function orders(uint256 orderId) external view returns (
        address owner_,
        uint256 amount,
        uint256 price,
        uint256 filledAmount,
        uint256 remainingAmount,
        uint256 timestamp,
        uint8 status,
        uint8 orderType
    ) {
        Order storage order = _orders[orderId];
        return (
            order.owner,
            order.amount,
            order.price,
            order.filledAmount,
            order.remainingAmount,
            order.timestamp,
            order.status,
            order.orderType
        );
    }

    function getRemainingAmount(uint256 orderId) external view returns (uint256) {
        return _orders[orderId].remainingAmount;
    }

    function isOrderExpired(uint256 orderId) external view returns (bool) {
        Order storage order = _orders[orderId];
        if (order.status != 1) return false;
        return block.timestamp > order.timestamp + _ttl;
    }

    function divisor() external pure returns (uint256) {
        return DIVISOR;
    }

    function maxFeePercentage() external pure returns (uint256) {
        return MAX_FEE_PERCENTAGE;
    }

    function getReserves(address pair) external view returns (uint112 reserve0, uint112 reserve1, uint32 blockTimestampLast) {
        return IUniswapV2Pair(pair).getReserves();
    }

    function cancelOrder(uint256 orderId) external nonReentrant {
        Order storage order = _orders[orderId];
        if (order.owner != msg.sender) revert CallerIsNotAuthorized();
        if (order.status != 1) revert OrderNotActive();
        order.status = 3;
        emit OrderCancelled(orderId);
    }

    receive() external payable {}
}
